    <div id="list"></div>
    <div id="rtfoot">✦ Marionetta · relationship ledger ✦</div>
  </div>
</div>

<script>
(function(){
function g(id){return document.getElementById(id)}
function esc(v){if(v==null)return'';return String(v).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;')}

var raw=g('rtraw');var d=null;
if(raw&&raw.value.trim()){
  var dec=document.createElement('textarea');dec.innerHTML=raw.value.trim();
  try{d=JSON.parse(dec.value.trim())}catch(e){}
}
if(!d)d={};
var rels=(d.relationships||[]).slice();
rels.sort(function(a,b){return (b.closeness||0)-(a.closeness||0)});

function tierInfo(c){
  c=parseFloat(c)||0;
  if(c<20)return{lbl:'Severed'};
  if(c<40)return{lbl:'Frayed'};
  if(c<60)return{lbl:'Loose Thread'};
  if(c<80)return{lbl:'Bound'};
  return{lbl:'Unbreakable'};
}
function warmthColor(w){
  w=(w||'neutral').toLowerCase();
  if(w==='warm')return getComputedStyle(document.documentElement).getPropertyValue('--warm').trim();
  if(w==='hostile')return getComputedStyle(document.documentElement).getPropertyValue('--hostile').trim();
  return getComputedStyle(document.documentElement).getPropertyValue('--neutral').trim();
}

function stringSVG(closeness,warmth){
  var c=Math.max(0,Math.min(100,parseFloat(closeness)||0));
  var sag=(100-c)/100*13+2; // 2px (taut) to 15px (slack) sag
  var col=warmthColor(warmth);
  var dash=(warmth==='hostile')?'3,3':'none';
  var midY=10+sag;
  return '<svg viewBox="0 0 300 22" preserveAspectRatio="none">'+
    '<path d="M10,10 Q150,'+midY+' 290,10" fill="none" stroke="'+col+'" stroke-width="1.6" stroke-dasharray="'+dash+'" opacity=".85"/>'+
    '<circle class="anchor" cx="10" cy="10" r="3"/>'+
    '<circle class="anchor" cx="290" cy="10" r="3" fill="'+col+'"/>'+
  '</svg>';
}

var listEl=g('list');
if(rels.length){
  listEl.innerHTML=rels.map(function(r){
    var tier=tierInfo(r.closeness);
    var col=warmthColor(r.warmth);
    var initial=(r.name||'?').trim().charAt(0).toUpperCase();
    var avatarInner=r.img?
      '<img src="https://files.catbox.moe/'+esc(r.img)+'" alt="'+esc(r.name)+'" onerror="this.style.display=\'none\'">':
      '';
    var moments=(r.moments||[]);
    var momentsH=moments.length?
      '<div class="moments">'+moments.map(function(m){return '<div class="moment-row"><span class="moment-mark">❦</span><span class="moment-txt">'+esc(m)+'</span></div>';}).join('')+'</div>':'';
    return '<div class="thread">'+
      '<div class="thread-top">'+
        '<div class="thr-avatar"><div class="thr-med">'+avatarInner+'<div class="thr-mono">'+esc(initial)+'</div></div></div>'+
        '<div class="thr-name-wrap">'+
          '<div class="thr-name">'+esc(r.name||'Unknown')+'</div>'+
          (r.status?'<div class="thr-status" style="color:'+col+';border-color:'+col+'66;background:'+col+'14">'+esc(r.status)+'</div>':'')+
        '</div>'+
        '<div class="thr-tier" style="color:'+col+'">'+tier.lbl+'<br><span style="color:var(--mu);font-size:8px">'+(r.closeness!=null?r.closeness:0)+'/100</span></div>'+
      '</div>'+
      '<div class="string-wrap">'+stringSVG(r.closeness,r.warmth)+'</div>'+
      (r.note?'<div class="thr-note">'+esc(r.note)+'</div>':'')+
      momentsH+
    '</div>';
  }).join('');
}else{
  listEl.innerHTML='<div class="empty-note">No threads have been tied yet.</div>';
}

var mast=g('mast');
if(mast)mast.addEventListener('click',function(){g('rtwin').classList.toggle('closed')});
})();
</script>
</body>
</html>

